package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's membership standing from a points score. Points start at 0 and gain
 * 2 for a present email, 1 when namesakeCount is 0, 2 for a household of 3 or more, and 3
 * for a tenure of more than 365 days measured from the registration date. The score maps to
 * a level of 1 (0-1 points), 2 (2-3), 3 (4-5) or 4 (6 or more).
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    /** The membership points of {@code owner}. */
    public static int points(Owner owner) {
        return (owner.getEmail() != null ? 2 : 0)
            + (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)
            + (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3 ? 2 : 0)
            + (ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365 ? 3 : 0);
    }

    /** The membership level of {@code owner} (1-4), mapped from its {@link #points(Owner)}. */
    public static int of(Owner owner) {
        return Math.min(4, points(owner) / 2 + 1);
    }
}
package org.springframework.samples.petclinic.rest.controller.v1;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collection;
import java.util.HashSet;
import java.util.Set;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Builds an owner's customerCode in the form {@code <REGION>-<HASH8>}: the region derived
 * from the postcode, then the first 8 upper-case hex characters of SHA-256 over the
 * owner's normalized telephone and last name.
 */
public final class CustomerCodes {

    private CustomerCodes() {
    }

    /** The {@code <REGION>-<HASH8>} identity code for {@code owner}. */
    static String build(Owner owner, Collection<Owner> existing) {
        return deduplicate(region(owner) + "-" + hash8(owner.getTelephone() + owner.getLastName()), existing);
    }

    /** {@code code}, or the first {@code code-<n>} (n starting at 2) not held by an owner in {@code existing}. */
    private static String deduplicate(String code, Collection<Owner> existing) {
        Set<String> used = new HashSet<>();
        for (Owner owner : existing) {
            used.add(owner.getCustomerCode());
        }
        String candidate = code;
        for (int n = 2; used.contains(candidate); n++) {
            candidate = code + "-" + n;
        }
        return candidate;
    }

    /** The region code derived from {@code owner}'s postcode, falling back to its city, else {@code UNKNOWN}. */
    public static String region(Owner owner) {
        String prefix = owner.getPostcode() != null && owner.getPostcode().matches("[0-9]{4}")
            ? owner.getPostcode().substring(0, 2) : "";
        return switch (prefix) {
            case "20" -> "NSW";
            case "30" -> "VIC";
            case "40" -> "QLD";
            default -> switch (owner.getCity() == null ? "" : owner.getCity()) {
                case "Sydney" -> "NSW";
                case "Melbourne" -> "VIC";
                case "Brisbane" -> "QLD";
                default -> "UNKNOWN";
            };
        };
    }

    /** The first 8 upper-case hex characters of SHA-256 over {@code value}. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
}
package org.springframework.samples.petclinic.rest.controller.v1;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of duplicate detection: an owner's identity is its normalized telephone,
 * email and household id joined as {@code normalizedTelephone|email|householdId} (email and
 * household id empty when absent). Two owners collide only when their whole keys are equal, so
 * members of one household with different telephones stay distinct.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The derived identity key of {@code owner}; telephone is already E.164-normalized upstream. */
    public static String of(Owner owner) {
        return blank(owner.getTelephone()) + "|" + blank(owner.getEmail()) + "|" + blank(owner.getHouseholdId());
    }

    /** {@code true} when an existing owner has the exact same identity key as {@code candidate}. */
    static boolean isDuplicate(Owner candidate, Collection<Owner> existing) {
        String key = of(candidate);
        return existing.stream().anyMatch(other -> of(other).equals(key));
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }
}

